/*
 * build-defs.h -- generated by configure in an upstream build;
 * hand-answered here.
 *
 * ***THE PATHS ARE ARCHITECTURE-INDEPENDENT ON PURPOSE.***  They are
 * baked into the binary as string constants, so they cannot carry
 * `$objtype' -- and they do not need to: php's runtime files are
 * text.  `/sys/lib/ape/php' follows `cmd/bash/mkfile's
 * `-DLOCALEDIR="/sys/lib/ape/locale"', which is the same shape.
 * Only the BINARY is per-architecture, and the mkfile installs that
 * through `$BIN'.
 *
 * `PHP_EXTENSION_DIR' and the shared-library names are empty because
 * **Plan 9 has no dynamic linking** -- the same reason perl here has
 * no XS extensions and `HAVE_LIBDL' is unset in `php_config.h'.  A
 * path would be a promise nothing can keep.
 */

#define CONFIGURE_COMMAND	"hand-answered for APExp; see sys/src/ape/cmd/php/mkfile"
#define PHP_PROG_SENDMAIL	""
#define PEAR_INSTALLDIR		""
#define PHP_INCLUDE_PATH	".:/sys/lib/ape/php"
#define PHP_EXTENSION_DIR	""
#define PHP_PREFIX		"/sys/lib/ape/php"
#define PHP_BINDIR		"/bin/ape"
#define PHP_SBINDIR		"/bin/ape"
#define PHP_MANDIR		"/sys/man"
#define PHP_LIBDIR		"/sys/lib/ape/php"
#define PHP_DATADIR		"/sys/lib/ape/php"
#define PHP_SYSCONFDIR		"/sys/lib/ape/php"
#define PHP_LOCALSTATEDIR	"/tmp"
#define PHP_CONFIG_FILE_PATH	"/sys/lib/ape/php"
#define PHP_CONFIG_FILE_SCAN_DIR	""
#define PHP_SHLIB_SUFFIX	""
#define PHP_SHLIB_EXT_PREFIX	""
